// Runs a typed, native-argv Operation (ADR-0001 — never a shell) against
// every Node the Selector matches. Requires the `operator` role.
//
// With `plan: true` this resolves, authorizes, and checks exactly as a
// real run would but **executes nothing**, returning per-Node Policy
// verdicts instead (ADR-0011). A plan creates no Job, so its response
// carries no `job_id`.
//
// Argument NAMES are validated against the Operation's published
// constraints before dispatch, so a misspelled argument is a `400` rather
// than a Policy denial. See `GET /api/v1/operations`… (vocabulary
// discovery is an MCP surface today; the argument names and constraints
// are the same on both).
//
// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
//
// Corresponds with POST /api/v1/operations (the `RunOperation` operationId).
func (c *ClientWithResponses) RunOperationWithResponse(ctx context.Context, body RunOperationJSONRequestBody, reqEditors ...RequestEditorFn) (*RunOperationResponse, error) {
	rsp, err := c.RunOperation(ctx, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseRunOperationResponse(rsp)
}

// RawExecWithBodyWithResponse Run an arbitrary argv (or plan it) — admin only
//
// ADR-0001's regex-gated escape hatch. `argv` runs verbatim — no shell, no
// client-side splitting — and the daemon's Policy regex decides per Node
// whether it is allowed.
//
// **Requires the `admin` role**, enforced centrally in the capability
// layer. Always risk class `mutate` regardless of what the command does,
// so it always takes the strict mutate blast cap (ADR-0012): a
// read-only-looking command is still unclassifiable, and "this command
// only reads" is exactly the claim an arbitrary-command path cannot make
// on its own behalf.
//
// Prefer `POST /api/v1/operations` whenever a structured Operation
// expresses the task.
//
// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
//
// Corresponds with POST /api/v1/raw-exec (the `RawExec` operationId).
func (c *ClientWithResponses) RawExecWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*RawExecResponse, error) {
	rsp, err := c.RawExecWithBody(ctx, contentType, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseRawExecResponse(rsp)
}

